W.logo = function (cls, x, y, size) {
  return '<svg class="' + cls + '" x="' + (x - size / 2) + '" y="' + (y - size / 2) + '" width="' + size + '" height="' + size + '" viewBox="0 0 512 512" style="overflow:visible">' + W.logoArt + '</svg>';
};

// ── Small motion helpers shared by the Sensei-week shorts ───────────────────────────────────────
// Fade and rise in from t0; pop (scale with overshoot) from t0; draw an SVG path (pathLength="1") between a and b.
W.fade = function (el, t, t0, K, d, dy) {
  const p = K.eo(K.seg(t, t0, t0 + (d || 0.5)));
  el.style.opacity = p.toFixed(3);
  el.style.transform = 'translateY(' + K.lerp(dy == null ? 18 : dy, 0, p).toFixed(1) + 'px)';
  return p;
};
W.pop = function (el, t, t0, K, base) {
  const p = K.seg(t, t0, t0 + 0.4);
  el.style.opacity = K.eo(p).toFixed(3);
  el.style.transform = (base || '') + ' scale(' + K.lerp(0.5, 1, K.eob(p, 1.8)).toFixed(3) + ')';
  return p;
};
W.draw = function (path, t, a, b, K) {
  const p = K.eio(K.seg(t, a, b));
  path.style.strokeDasharray = '1 1';
  path.style.strokeDashoffset = (1 - p).toFixed(4);
  return p;
};
// Code lines as rounded bars: rows of [indent, width, tone] inside an SVG, from (x, y), row gap g.
W.bars = function (cls, x, y, rows, g, h) {
  return rows.map(([i, w, tone], k) => '<rect class="' + cls + '" x="' + (x + i) + '" y="' + (y + k * (g || 34)) + '" width="' + w + '" height="' + (h || 12) + '" rx="' + (h || 12) / 2 +
    '" style="fill:' + (tone === 'hot' ? 'var(--accent)' : tone === 'ok' ? 'var(--jade)' : tone === 'ink' ? 'var(--main)' : 'var(--hair)') + '"/>').join('');
};
